        add("wiki.cyberneticenhancements.chipware.installation.host_only", "Chipware only functions inside cyberware that exposes chip slots.");
        add("wiki.cyberneticenhancements.chipware.installation.slot_count", "The active chip slot count comes from the host implant and its upgrade state.");
        add("wiki.cyberneticenhancements.station.ripper.subtitle", "Install, compare and manage cyberware, chipware and modules.");
        add("wiki.cyberneticenhancements.station.ripper.overview.1", "The Ripper Station is the main body-management screen.");
        add("wiki.cyberneticenhancements.station.ripper.overview.2", "It exposes body slots, current installed hardware, chrome totals and slot-by-slot planning.");
        add("wiki.cyberneticenhancements.station.ripper.functions.1", "Install and remove cyberware.");
        add("wiki.cyberneticenhancements.station.ripper.functions.2", "Inspect passive effects, active implants, upgrade level and integrity.");
        add("wiki.cyberneticenhancements.station.ripper.functions.3", "Manage chipware and modules when the selected implant supports them.");
        add("wiki.cyberneticenhancements.station.ripper.functions.4", "Open the archive directly from the station UI.");
        add("wiki.cyberneticenhancements.station.tech.subtitle", "Repair damaged cyberware and apply upgrade levels.");
        add("wiki.cyberneticenhancements.station.tech.overview.1", "The Tech Station handles restoration and upgrade work for cyberware items.");
        add("wiki.cyberneticenhancements.station.tech.overview.2", "Repair costs scale with missing integrity and item tier.");
        add("wiki.cyberneticenhancements.station.tech.overview.3", "Upgrade costs double each level and cap at one stack per required material.");
        add("wiki.cyberneticenhancements.station.tech.functions.1", "Show repair materials for damaged cyberware.");
        add("wiki.cyberneticenhancements.station.tech.functions.2", "Show upgrade materials for the next upgrade level.");
        add("wiki.cyberneticenhancements.station.tech.functions.3", "Return a fully repaired output item for both repair and upgrade plans.");
        add("wiki.cyberneticenhancements.station.recycler.subtitle", "Break down cyberware, modules, chipware and consumables into reusable parts.");
        add("wiki.cyberneticenhancements.station.recycler.overview.1", "The Recycler Station reads recycler recipes and converts hardware into fixed salvage outputs.");
        add("wiki.cyberneticenhancements.station.recycler.overview.2", "Cyberware items also return their slot support material in addition to the main recycled result.");
        add("wiki.cyberneticenhancements.station.recycler.functions.1", "Recycle cyberware into tier components plus slot support material.");
        add("wiki.cyberneticenhancements.station.recycler.functions.2", "Recycle modules into replacement joints.");
        add("wiki.cyberneticenhancements.station.recycler.functions.3", "Recycle chipware into tier components.");
        add("wiki.cyberneticenhancements.station.recycler.functions.4", "Recycle consumables into wiring, paste or circuit plates by category.");
        add("wiki.cyberneticenhancements.station.relic_cache.title", "Relic Caches");
        add("wiki.cyberneticenhancements.station.relic_cache.subtitle", "Tiered breach caches placed into high-value structures.");
        add("wiki.cyberneticenhancements.station.relic_cache.overview.1", "Each placed Relic Cache keeps its own matrix and daemon list until that cache is opened.");
        add("wiki.cyberneticenhancements.station.relic_cache.overview.2", "The first time you open a cache, a 60 second breach timer starts. Closing the screen does not pause or reset it.");
        add("wiki.cyberneticenhancements.station.relic_cache.overview.3", "Uncommon caches seed early utility hardware, rare caches upgrade that pool, epic caches start dropping high-end systems, and legendary caches are reserved for the strongest structure finds.");
        add("wiki.cyberneticenhancements.station.relic_cache.spawn_sites.1", "Uncommon caches replace one chest or barrel in igloo basements, jungle temples and pillager outposts.");
        add("wiki.cyberneticenhancements.station.relic_cache.spawn_sites.2", "Rare caches replace one chest or barrel in desert pyramids, woodland mansions and strongholds.");
        add("wiki.cyberneticenhancements.station.relic_cache.spawn_sites.3", "Epic caches replace one chest or barrel in trial chambers, ancient cities and bastion remnants.");
        add("wiki.cyberneticenhancements.station.relic_cache.spawn_sites.4", "Legendary caches replace one chest or barrel in end cities.");
        add("wiki.cyberneticenhancements.station.relic_cache.spawn_sites.5", "Each cleared cache always rolls one primary reward, then one or two support rewards from that tier's support pool.");
        add("wiki.cyberneticenhancements.station.relic_cache.functions.1", "Select tokens from the highlighted top row first, then alternate between the matching column and matching row.");
        add("wiki.cyberneticenhancements.station.relic_cache.functions.2", "A daemon is cleared once its full token sequence appears anywhere in the path you have built.");
        add("wiki.cyberneticenhancements.station.relic_cache.functions.3", "Clear every daemon before the timer expires to start the loot release sequence.");
        add("wiki.cyberneticenhancements.station.relic_cache.functions.4", "Daemons do not grant separate effects or partial rewards. The cache opens only when every listed daemon is cleared.");
        add("wiki.cyberneticenhancements.station.relic_cache.example.grid_label", "Example Route");
        add("wiki.cyberneticenhancements.station.relic_cache.example.daemon_label", "Daemon Chain");
        add("wiki.cyberneticenhancements.station.relic_cache.example.1", "Start on the highlighted top-row cell marked 1. That gives you the first token, 55.");
        add("wiki.cyberneticenhancements.station.relic_cache.example.2", "Your second pick must stay in the same column, so move down to step 2 for BD, then across that row to step 3 for 4C.");
        add("wiki.cyberneticenhancements.station.relic_cache.example.3", "At that point Daemon 1 is already cleared, because 55 BD 4C now appears in your path.");
        add("wiki.cyberneticenhancements.station.relic_cache.example.4", "From step 3, move down the same column to FF, then across the last row to 0A. Those last two picks clear Daemon 2 as BD 4C FF and Daemon 3 as 4C FF 0A.");
        add("wiki.cyberneticenhancements.station.relic_cache.how_to_manage.1", "Start by scanning the daemon sequences on the right and look for shared middle or ending tokens.");
        add("wiki.cyberneticenhancements.station.relic_cache.how_to_manage.2", "Because the path only has to contain the sequence, you can route one daemon into another instead of solving each one separately.");
        add("wiki.cyberneticenhancements.station.relic_cache.how_to_manage.3", "Selected cells are numbered on the grid, so you can review the full route directly while planning the next pick.");
        add("wiki.cyberneticenhancements.station.relic_cache.how_to_manage.4", "Hovered cells show whether the current line is legal. If a token is off the active row or column, it cannot be picked yet.");
        add("wiki.cyberneticenhancements.station.relic_cache.how_to_manage.5", "You can close the screen to deal with combat or reposition, then reopen the same cache and continue the same run if time remains.");
        add("wiki.cyberneticenhancements.section.example_solution", "Example Solution");
        add("wiki.cyberneticenhancements.npc.general", "General");
        add("wiki.cyberneticenhancements.npc.general.subtitle", "Shared NPC rules, contact tracking and identity behavior across the whole NPC layer.");
        add("wiki.cyberneticenhancements.npc.general.overview.1", "Mod NPCs are built as persistent contacts, not as villager trade wrappers. They keep identity, home data and per-player relationship state.");
        add("wiki.cyberneticenhancements.npc.general.overview.2", "Each player keeps separate trust and interaction flags with the same NPC, so multiplayer use of one contact does not merge progression between players.");
        add("wiki.cyberneticenhancements.npc.general.overview.3", "NPCs use player-style skins and rendering, can be called through the archive, and are meant to stay relevant beyond a single screen click.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.1", "The Contacts tab records every NPC you have actually interacted with. Each card shows the head render, name, type, trust state and live or last known location.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.2", "The contact list has its own filters: All, one tab per NPC type, Pinned and Hidden. Hidden contacts are excluded from All and from the type tabs until you open Hidden directly.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.3", "Each card supports Pin or Unpin plus Hide or Unhide. These flags are stored per player, so one player's organization does not change another player's archive.");
        add("wiki.cyberneticenhancements.npc.general.contacts_archive.4", "Locate outlines a loaded contact in your current dimension. Meet Up calls that contact to your position for a short window and then sends them back to their home point.");
        add("wiki.cyberneticenhancements.npc.general.identity_config.1", "NPC names and categories come from config/cyberneticenhancements-npc-identities.properties.");
        add("wiki.cyberneticenhancements.npc.general.identity_config.2", "The file separates male_names, female_names and generic_names. The chosen category also selects the texture folder under assets/cyberneticenhancements/textures/entity/npc/<category>/.");
        add("wiki.cyberneticenhancements.npc.general.identity_config.3", "Skins are rendered on the player model with second-layer parts enabled, so hats, jackets and similar overlay pixels show if the texture provides them.");
        add("wiki.cyberneticenhancements.npc.general.current_state.1", "The shared identity, archive and per-player relation systems are already built for multiple NPC archetypes, even though only one type is live today.");
        add("wiki.cyberneticenhancements.npc.general.current_state.2", "Future NPC types can reuse the same contact indexing, trust storage, meet-up flow and config-based identity pool.");
        add("wiki.cyberneticenhancements.npc.fixer", "Fixer");
        add("wiki.cyberneticenhancements.npc.fixer.subtitle", "Player-focused broker contacts that handle stabilization, stock, trust and relic-route intel.");
        add("wiki.cyberneticenhancements.npc.fixer.overview.1", "Fixers are the first live NPC archetype in the mod.");
        add("wiki.cyberneticenhancements.npc.fixer.overview.2", "They open a dialogue-driven contact screen, sell controlled stock and expose clinic-style services instead of using villager trades.");
        add("wiki.cyberneticenhancements.npc.fixer.overview.3", "Every player keeps a separate relationship with the same fixer, so trust, meeting state and daily purge access do not collide in multiplayer.");
        add("wiki.cyberneticenhancements.npc.fixer.field_presence.1", "Fixers now spawn through Night City settlements instead of vanilla villages. The current Night City layout reuses vanilla village buildings while custom cyberpunk architecture is still pending.");
        add("wiki.cyberneticenhancements.npc.fixer.field_presence.2", "A fixer prioritizes the current customer first, then high-pressure patients, then nearby players it has not met yet, instead of wandering with random villager logic.");
        add("wiki.cyberneticenhancements.npc.fixer.field_presence.3", "Every fixer spawned in a Night City settlement anchors to that settlement's center meeting point as home, and spawn-egg fixers use their egg placement coordinates as home.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.1", "The first proper business introduction marks that fixer as known and gives a small opening trust bump.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.2", "Successful paid services and purchases keep raising trust on a long 0-100%% progression. Max trust now takes sustained repeat business instead of a handful of transactions.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.3", "Trust is stored per player and per fixer UUID. Building rapport with one fixer does not automatically unlock another.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.4", "Trust can also be lost again. Attacking a fixer, wasting a meetup without spending anything, or repeatedly trying to buy work you cannot afford will all drag the relationship back down.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.5", "Push too much annoyance into a short window and the fixer reacts temporarily: prices spike hard, or they refuse to work with you and stop giving you attention until that heat dies down.");
        add("wiki.cyberneticenhancements.npc.fixer.trust_model.6", "The current live heat timings are short-term but real: enough annoyance can trigger roughly a 2 minute price spike or about a 4 minute refusal window before the fixer works normally again.");
        add("wiki.cyberneticenhancements.npc.fixer.services.1", "Stabilize Systems is available immediately and applies a short suppression dose.");
        add("wiki.cyberneticenhancements.npc.fixer.services.2", "Chrome Suppressant stock unlocks at Trust 1.");
        add("wiki.cyberneticenhancements.npc.fixer.services.3", "Full Purge unlocks at Trust 2. It clears negative instability pressure and can be used once per in-game day for that player with that fixer.");
        add("wiki.cyberneticenhancements.npc.fixer.services.4", "Immunoblockers unlock at Trust 3.");
        add("wiki.cyberneticenhancements.npc.fixer.services.5", "Trust also lowers fixer prices. Discounts now scale by trust percentage, up to 25% at maximum trust.");
        add("wiki.cyberneticenhancements.npc.fixer.account_and_stock.1", "Fixers do not take emeralds. Every transaction withdraws from the player's eurodollar account.");
        add("wiki.cyberneticenhancements.npc.fixer.account_and_stock.2", "Base stock is MaxDoc Mk.2 and RAM Jolt. Higher trust adds Chrome Suppressant and Immunoblockers.");
        add("wiki.cyberneticenhancements.npc.fixer.account_and_stock.3", "Server operators can inspect or adjust balances with the money commands: balance, set, add, remove and change.");
        add("wiki.cyberneticenhancements.npc.fixer.current_state.1", "Only the fixer archetype is implemented right now, but it already covers contact dialogue, stock, services, trust and relic-cache intel.");
        add("wiki.cyberneticenhancements.npc.fixer.current_state.2", "Contracts and deeper story jobs are still future work on top of the live fixer base.");
        add("wiki.cyberneticenhancements.system.cyberstrain.subtitle", "The pressure system that limits how much chrome a body can run safely.");
        add("wiki.cyberneticenhancements.system.cyberstrain.threshold.strained", "Strained: %s");
        add("wiki.cyberneticenhancements.system.cyberstrain.threshold.unstable", "Unstable: %s");
        add("wiki.cyberneticenhancements.system.cyberstrain.threshold.critical", "Critical: %s");
        add("wiki.cyberneticenhancements.system.cyberstrain.threshold.psychosis", "Psychosis Risk: %s");
        add("wiki.cyberneticenhancements.system.cyberstrain.change.1", "Higher cyberstrain applies passive penalties to movement, attack speed, healing, ability cooldowns and max health.");
        add("wiki.cyberneticenhancements.system.cyberstrain.change.2", "Suppression medicine temporarily reduces effective cyberstrain.");
        add("wiki.cyberneticenhancements.system.cyberstrain.change.3", "Frontal cortex hardware can add extra cyberstrain on top of installed chrome.");
        add("wiki.cyberneticenhancements.system.cyberstrain.manage.1", "Use lower-cost implants for early builds.");
        add("wiki.cyberneticenhancements.system.cyberstrain.manage.2", "Use suppressants when pushing into high-strain setups.");
        add("wiki.cyberneticenhancements.system.cyberstrain.manage.3", "Treat active cyberware and stimulant use as part of the risk budget, not just the installed load.");
        add("wiki.cyberneticenhancements.system.psychosis.subtitle", "High-strain crisis behavior driven by effective cyberstrain plus instability.");
        add("wiki.cyberneticenhancements.system.psychosis.trigger.1", "Cyberpsychosis does not trigger from installed chrome alone. It requires psychosis-risk cyberstrain plus accumulated instability.");
        add("wiki.cyberneticenhancements.system.psychosis.trigger.2", "Instability builds from combat, cyberware activations, certain consumables and staying in the danger bands.");
        add("wiki.cyberneticenhancements.system.psychosis.tiers.1", "Minor episode: aggressive surge with boosted combat stats and control pressure, but not the full major takeover.");
        add("wiki.cyberneticenhancements.system.psychosis.tiers.2", "Major episode: full hostile autopilot, target pursuit, top-screen server tracker and major penalty package.");
        add("wiki.cyberneticenhancements.system.psychosis.stabilization.1", "Immunoblockers and Chrome Suppressant reduce instability and can shorten an active episode.");
        add("wiki.cyberneticenhancements.system.psychosis.stabilization.2", "After an episode ends, Aftershock remains briefly and keeps some penalties active.");
        add("wiki.cyberneticenhancements.system.psychosis.targeting.1", "Major episodes prioritize players first, hostile mobs second and untamed land animals last.");
        add("wiki.cyberneticenhancements.system.psychosis.targeting.2", "Ignored targets include configured nuisance types such as bats, fish, silverfish and endermites.");
        add("wiki.cyberneticenhancements.system.progression.subtitle", "The live acquisition split and implemented world sources.");
        add("wiki.cyberneticenhancements.system.progression.craftable.1", "Starter cyberware, all chipware, all modules and all consumables have live recipe support.");
        add("wiki.cyberneticenhancements.system.progression.craftable.2", "That keeps the baseline build path reliable even before you find any structure loot.");
        add("wiki.cyberneticenhancements.system.progression.craftable.3", "Several starter implants also show up in uncommon relic caches, so early progression can be crafted or found.");
        add("wiki.cyberneticenhancements.system.progression.loot.1", "Relic Cache world generation is live. Each supported structure replaces one chest or barrel with a tiered cache block.");
        add("wiki.cyberneticenhancements.system.progression.loot.2", "Uncommon: igloo basement, jungle temple, pillager outpost. Rare: desert pyramid, woodland mansion, stronghold.");
        add("wiki.cyberneticenhancements.system.progression.loot.3", "Epic: trial chambers, ancient city, bastion remnant. Legendary: end city.");
        add("wiki.cyberneticenhancements.system.progression.quest.1", "The quest layer is now live through fixers. Current contracts cover delivery runs, hostile cleanup and recovery pulls, all tracked in the quest archive.");
        add("wiki.cyberneticenhancements.system.progression.quest.2", "Quest rewards stay controlled: eurodollars, small trust gains and light consumable support. High-end cyberware progression still leans on relic caches and structure loot.");
        add("wiki.cyberneticenhancements.system.progression.state.1", "If an item says no live source is wired yet, it is classified for loot progression but is not currently granted by a cache or other world system.");
        add("wiki.cyberneticenhancements.system.progression.state.2", "Use each item's Acquisition section for exact cache tier, structure list and per-roll odds.");
